const wb=$('Webhook').first().json.body||{};
const name=wb.customer_name||'Unknown';
const rows=$('Get Cycles').all().filter(r=>r.json&&r.json.customer_id);
if(!rows.length){
  return [{json:{error:true,message:'Customer not found: '+name,
    churn_probability:0,recommended_action:'not_found',retention_recommendation:'Customer not found in database.',chronic_drugs:[],llm_source:'system'}}];
}
const r=rows[0].json;
const avg=parseFloat(r.avg_cycle_days)||30;
const oc=parseInt(r.order_count)||0;
let ds=0,cp=0.05;
if(r.last_purchase_date){
  ds=Math.floor((Date.now()-new Date(r.last_purchase_date).getTime())/(1000*60*60*24));
  if(ds>avg)cp=Math.min(0.95,(ds-avg)/avg);
}
const prompt='Customer retention for '+r.full_name+'. Last purchase: '+ds+' days ago (avg cycle: '+Math.round(avg)+' days). Churn probability: '+(cp*100).toFixed(0)+'%. Orders: '+oc+'. Suggest a 2-sentence retention action plan.';
return [{json:{customer_id:r.customer_id,full_name:r.full_name,order_count:oc,last_purchase_days_ago:ds,avg_cycle_days:Math.round(avg),churn_probability:parseFloat(cp.toFixed(2)),high_risk:cp>0.7,ollama_prompt:prompt,error:false}}];

const calc=$('Calc Churn').first().json;
if(calc.error)return [{json:calc}];
const rec=$('Ask Ollama').first().json.response||'';
let action='monitor';
if(calc.churn_probability>=0.7)action='urgent_intervention';
else if(calc.churn_probability>=0.4)action='send_offer';
else if(calc.churn_probability>=0.2)action='send_reminder';
return [{json:{
  customer_name:calc.full_name,order_count:calc.order_count,last_purchase_days_ago:calc.last_purchase_days_ago,
  avg_cycle_days:calc.avg_cycle_days,churn_probability:calc.churn_probability,
  risk_level:calc.churn_probability>=0.7?'high':calc.churn_probability>=0.4?'medium':'low',
  recommended_action:action,retention_recommendation:rec.trim(),chronic_drugs:[],llm_source:'ollama:AI-COS-LFM-Q4'
}}];
